 function ensureOperation(epoch,snapshot){if(operationEpoch!==epoch||!host?.isConnected||state.connection!=='connected'||state.address!==snapshot.address||state.provider!==snapshot.provider||quoteRevision!==snapshot.quoteRevision||Date.now()>=snapshot.quote.expiresAt){const error=Error('Stale wallet operation');error.name='AbortError';throw error;}}
