 function expectedOperation(cfg,snapshot){return {publicKey:snapshot.address,transactionSource:snapshot.address,operationSource:snapshot.address,destinationAccount:snapshot.address,network:cfg.network,sourceAsset:normalizeAsset({code:cfg.quoteCode,issuer:cfg.quoteIssuer}),destinationAsset:normalizeAsset({code:cfg.code,issuer:cfg.issuer}),sourceAmount:snapshot.quote.sendAmount,destinationMin:snapshot.quote.minimum,path:snapshot.quote.path,operationType:'path_payment_strict_send',operationCount:1,memoType:'none',timeBounds:{minTime:'0',maxTime:String(Math.floor(snapshot.quote.expiresAt/1000))},maxFeeStroops:'100000'};}
